--
-- Table structure for table `job_postings`
--

DROP TABLE IF EXISTS `job_postings`;
/*!40101 SET @saved_cs_client     = @@character_set_client */;
/*!50503 SET character_set_client = utf8mb4 */;
CREATE TABLE `job_postings` (
  `job_id` int NOT NULL AUTO_INCREMENT,
  `company_id` int DEFAULT NULL,
  `recruiter_id` int NOT NULL,
  `title` varchar(500) NOT NULL,
  `description` text,
  `seniority_level` varchar(100) DEFAULT NULL,
  `employment_type` varchar(100) DEFAULT NULL,
  `location` varchar(255) DEFAULT NULL,
  `work_mode` enum('remote','hybrid','onsite') DEFAULT 'onsite',
  `skills_required` json DEFAULT NULL,
  `salary_min` decimal(12,2) DEFAULT NULL,
  `salary_max` decimal(12,2) DEFAULT NULL,
  `posted_datetime` timestamp NULL DEFAULT CURRENT_TIMESTAMP,
  `status` enum('open','closed') DEFAULT 'open',
  `views_count` int DEFAULT '0',
  `applicants_count` int DEFAULT '0',
  `created_at` timestamp NULL DEFAULT CURRENT_TIMESTAMP,
  `updated_at` timestamp NULL DEFAULT CURRENT_TIMESTAMP ON UPDATE CURRENT_TIMESTAMP,
  PRIMARY KEY (`job_id`),
  KEY `idx_status` (`status`),
  KEY `idx_recruiter` (`recruiter_id`),
  KEY `idx_posted` (`posted_datetime`),
  FULLTEXT KEY `idx_job_search` (`title`,`description`),
  CONSTRAINT `job_postings_ibfk_1` FOREIGN KEY (`recruiter_id`) REFERENCES `recruiters` (`recruiter_id`) ON DELETE CASCADE
) ENGINE=InnoDB AUTO_INCREMENT=51 DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_0900_ai_ci;
/*!40101 SET character_set_client = @saved_cs_client */;

--
-- Dumping data for table `job_postings`
--

LOCK TABLES `job_postings` WRITE;
/*!40000 ALTER TABLE `job_postings` DISABLE KEYS */;
